<style scoped lang="scss" src="./text-input.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import {
  TextInputMode,
  TextInputModeValues
} from "./text-input.constants";

@Component
export default class TextInput extends Vue {
  @Prop({ type: [Number, String], default: "" }) value;
  @Prop({ type: Boolean, default: false }) readOnly;
  @Prop({ type: String, default: "" }) placeholder;
  @Prop({
    type: String,
    default: TextInputMode.DEFAULT,
    validator: has(TextInputModeValues)
  })
  mode;

  isPassword = false;
  focused = false;
  hovered = false;

  get hoverClass() {
    return this.hovered ? "TextInput--hovered" : "TextInput--unhovered";
  }

  get focusClass() {
    return this.focused ? "TextInput--focused" : "TextInput--unfocused";
  }

  get readOnlyClass() {
    return this.readOnly ? "TextInput--readonly" : "TextInput--active";
  }

  get modeClass() {
    return this.mode;
  }

  handleInput() {
    /**
     * Change input event. Fires when the value of this field changes and
     * proivides the current value.
     *
     * @event input
     */
    this.$emit("input", this.$refs.inputField.value);
  }

  handleFocus() {
    if (!this.readOnly) {
      this.focused = true;
    }
  }

  handleBlur() {
    this.focused = false;
  }

  handleOver() {
    this.hovered = true;
  }

  handleOut() {
    this.hovered = false;
  }
}
</script>

<template>
  <div
    :class="['TextInput', hoverClass, focusClass, readOnlyClass, modeClass]"
    @mouseover="handleOver"
    @mouseout="handleOut"
  >
    <input
      class="TextInput__TextField"
      :readonly="readOnly"
      spellCheck="false"
      autoCorrect="false"
      ref="inputField"
      :type="isPassword ? 'password' : 'text'"
      :value="value"
      :placeholder="placeholder"
      @input="handleInput"
      @focus="handleFocus"
      @blur="handleBlur"
    />
  </div>
</template>
